288	    private static string BuildCsvRow(IReadOnlyList<string> fields, IReadOnlyList<int> selectedIndexes)
289	    {
290	        var selectedFields = new string[selectedIndexes.Count];
291	        for (var i = 0; i < selectedIndexes.Count; i++)
292	        {
293	            var selectedIndex = selectedIndexes[i];
294	            selectedFields[i] = selectedIndex < fields.Count ? EscapeCsvField(fields[selectedIndex]) : string.Empty;
295	        }
296	
297	        return string.Join(",", selectedFields);
298	    }
