301	    {
302	        var outputFields = new string[fields.Count];
303	        for (var i = 0; i < fields.Count; i++)
304	        {
305	            outputFields[i] = EscapeCsvField(fields[i]);
306	        }
307	
308	        return string.Join(",", outputFields);
