311	    private static bool TryResolveRequestedColumnIndexes(
312	        IReadOnlyList<string> headers,
313	        IReadOnlyList<string> requestedColumns,
314	        out int[] selectedIndexes,
315	        out string? errorMessage)
316	    {
317	        selectedIndexes = new int[requestedColumns.Count];
318	
319	        for (var i = 0; i < requestedColumns.Count; i++)
320	        {
321	            var requestedColumn = requestedColumns[i];
322	            var index = -1;
323	            for (var headerIndex = 0; headerIndex < headers.Count; headerIndex++)
324	            {
325	                if (string.Equals(headers[headerIndex], requestedColumn, StringComparison.OrdinalIgnoreCase))
326	                {
327	                    index = headerIndex;
328	                    break;
329	                }
330	            }
331	
332	            if (index < 0)
333	            {
334	                errorMessage = $"Column not found: {requestedColumn}";
335	                selectedIndexes = Array.Empty<int>();
336	                return false;
337	            }
338	
339	            selectedIndexes[i] = index;
340	        }
341	
342	        errorMessage = null;
343	        return true;
344	    }
