358	    private static SortValue GetSortValue(IReadOnlyList<string> fields, int sortColumnIndex)
359	    {
360	        var value = sortColumnIndex < fields.Count ? fields[sortColumnIndex] : string.Empty;
361	        if (decimal.TryParse(value, NumberStyles.Number, CultureInfo.InvariantCulture, out var numericValue))
362	        {
363	            return new SortValue(true, numericValue, value);
364	        }
365	
366	        return new SortValue(false, default, value);
367	    }
