369	    private static bool TryParseSortDirection(
370	        string? directionArgument,
371	        out SortDirection sortDirection,
372	        out string? errorMessage)
373	    {
374	        if (directionArgument is null)
375	        {
376	            sortDirection = SortDirection.Ascending;
377	            errorMessage = null;
378	            return true;
379	        }
380	
381	        if (string.Equals(directionArgument, "asc", StringComparison.OrdinalIgnoreCase))
382	        {
383	            sortDirection = SortDirection.Ascending;
384	            errorMessage = null;
385	            return true;
386	        }
387	
388	        if (string.Equals(directionArgument, "desc", StringComparison.OrdinalIgnoreCase))
389	        {
390	            sortDirection = SortDirection.Descending;
391	            errorMessage = null;
392	            return true;
393	        }
394	
395	        sortDirection = SortDirection.Ascending;
396	        errorMessage = $"Invalid sort direction: {directionArgument}";
397	        return false;
398	    }
