437	    private static string EscapeCsvField(string value)
438	    {
439	        if (value.Length == 0)
440	        {
441	            return string.Empty;
442	        }
443	
444	        var requiresQuoting = value.Contains(',') ||
445	            value.Contains('"') ||
446	            value.Contains('\r') ||
447	            value.Contains('\n');
448	
449	        if (!requiresQuoting)
450	        {
451	            return value;
452	        }
453	
454	        var escaped = value.Replace("\"", "\"\"");
455	        return $"\"{escaped}\"";
456	    }
