462	    private sealed class StringArraySequenceComparer : IEqualityComparer<string[]>
463	    {
464	        public bool Equals(string[]? x, string[]? y)
465	        {
466	            if (ReferenceEquals(x, y))
467	            {
468	                return true;
469	            }
470	
471	            if (x is null || y is null || x.Length != y.Length)
472	            {
473	                return false;
474	            }
475	
476	            for (var i = 0; i < x.Length; i++)
477	            {
478	                if (!string.Equals(x[i], y[i], StringComparison.Ordinal))
479	                {
480	                    return false;
481	                }
482	            }
483	
484	            return true;
485	        }
486	
487	        public int GetHashCode(string[] obj)
488	        {
489	            var hashCode = new HashCode();
490	            foreach (var value in obj)
491	            {
492	                hashCode.Add(value, StringComparer.Ordinal);
493	            }
494	
495	            return hashCode.ToHashCode();
496	        }
497	    }
