505	    private sealed record CsvWhereClause(string ColumnName, ComparisonOperator Operator, string LiteralValue)
506	    {
507	        public static bool TryParse(string whereExpression, out CsvWhereClause clause, out string errorMessage)
508	        {
509	            var trimmedExpression = whereExpression?.Trim() ?? string.Empty;
510	            if (trimmedExpression.Length == 0)
511	            {
512	                clause = default!;
513	                errorMessage = "Invalid where expression.";
514	                return false;
515	            }
516	
517	            foreach (var candidate in ComparisonOperator.All)
518	            {
519	                var operatorIndex = trimmedExpression.IndexOf(candidate.Symbol, StringComparison.Ordinal);
520	                if (operatorIndex < 0)
